#include <bits/stdc++.h>
#define IOS ios::sync_with_stdio(0)
#define lowbit(x) ((x) & (-x))
#define int long long
using namespace std;

inline char getNextChar() {
    static char buffer[1000000], *p1 = buffer, *p2 = buffer;
    return p1 == p2 && (p2 = (p1 = buffer) + fread(buffer, 1, 1000000, stdin), p1 == p2) ? EOF : *p1++;
}

int getNextInt() {
    int sign = 1, num = 0;
    char ch = getNextChar();
    while (!isdigit(ch)) {
        if (ch == '-') sign = -1;
        ch = getNextChar();
    }
    while (isdigit(ch)) {
        num = num * 10 + (ch - '0');
        ch = getNextChar();
    }
    return sign * num;
}

void printNumber(int x) {
    if (x < 0) {
        putchar('-');
        printNumber(-x);
        return;
    }
    if (x >= 10) printNumber(x / 10);
    putchar(x % 10 + '0');
}

void printAnswer(int x) {
    printNumber(x);
    putchar('\n');
}

const int MOD1 = 998244353, MOD2 = 1000000007;
vector<int> val[10];
int n, cntA, cntB, total, sumArr[10], powArr[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

bool checkCond(int x) {
    int limit = 1000000;
    return x * limit + 999999 <= n && x * limit * 10 > n;
}

void buildVectors(int depth, int prefix) {
    if (depth == 7) return;
    val[depth].push_back((cntA - prefix + MOD1) % MOD1);
    sumArr[depth] += (cntA - prefix + MOD1) % MOD1;
    cntA++;
    for (int digit = 0; digit <= 9; digit++)
        buildVectors(depth + 1, prefix * 10 + digit);
}

void processNode(int depth, int current) {
    if (current > n) return;
    if (checkCond(current)) {
        for (int i = 0; i <= 6; i++) {
            int temp = ((cntB + 1 - (current * powArr[i])) % MOD1 + MOD1) % MOD1;
            int pos = lower_bound(val[i].begin(), val[i].end(), MOD1 - temp) - val[i].begin();
            total += (sumArr[i] + temp * (int)val[i].size() - MOD1 * ((int)val[i].size() - pos));
            total %= MOD2;
        }
        cntB += cntA;
    } else {
        cntB++;
        total += ((cntB - current) % MOD1 + MOD1) % MOD1;
        total %= MOD2;
        for (int d = (!depth); d <= 9; d++)
            processNode(depth + 1, current * 10 + d);
    }
}

int main() {
    n = getNextInt();
    buildVectors(0, 0);
    for (int i = 0; i <= 6; i++)
        sort(val[i].begin(), val[i].end());
    cntB = -1;
    processNode(0, 0);
    printAnswer(total);
}
